import type { Argv } from 'yargs'
import type { CicdArguments, ParamSpec } from './types'

export function camelToKebab(name: string): string {
    return name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()
}

export function camelToSnake(name: string): string {
    return name.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase()
}

/** Adds one yargs `.option()` per ParamSpec, deriving the CLI flag name from `name`, plus any declared `conflicts`. */
export function applyParamOptions(yargs: Argv, params: ParamSpec[]): Argv {
    let y = params.reduce(
        (acc, param) =>
            acc.option(camelToKebab(param.name), {
                describe: param.describe,
                type: param.type,
                ...(param.required ? { demandOption: true } : {}),
                ...(param.default !== undefined ? { default: param.default } : {}),
                ...(param.choices ? { choices: param.choices } : {}),
                ...(param.alias ? { alias: param.alias } : {}),
            }),
        yargs
    )

    for (const param of params) {
        for (const conflictName of param.conflicts ?? []) {
            y = y.conflicts(camelToKebab(param.name), camelToKebab(conflictName))
        }
    }

    return y
}

export interface ParamPayload {
    body: Record<string, unknown>
    query: URLSearchParams
}

/** Splits parsed CLI args into the request body fields and query string params declared by ParamSpec. */
export function extractParamPayload(params: ParamSpec[], args: CicdArguments): ParamPayload {
    const body: Record<string, unknown> = {}
    const query = new URLSearchParams()

    for (const param of params) {
        const value = args[param.name]
        if (value === undefined) {
            continue
        }
        if (param.location === 'path' || param.location === 'client') {
            continue
        }
        const apiName = param.apiName ?? camelToSnake(param.name)
        if (param.location === 'body') {
            body[apiName] = value
        } else {
            query.set(apiName, String(value))
        }
    }

    return { body, query }
}
